+            final CloseableHttpClient apacheHttpClient = HttpClients.custom()
+                .setSSLContext(SSLContexts.createSystemDefault())
+                .setConnectionManager(connManager)
+                .disableAutomaticRetries()
+                .setConnectionManagerShared(true)
+                .build();
