+        }
+    }
+
+    private void accumulateFailure(Exception e) {
+        if (failures == null) {
+            failures = new ArrayList<>(MAX_SUPPRESSED_EXCEPTIONS);
+        }
+        if (failures.size() < MAX_SUPPRESSED_EXCEPTIONS) {
+            failures.add(e);
+        }
+    }
+
+    private IOException addSuppressedFailures(IOException e) {
+        if (failures == null) {
